'use strict';
// The studio extends the existing authenticated Huddle lifecycle without replacing media ownership.
const HUDDLE_STUDIO={tool:'pointer',color:'cyan',draft:null,reports:[],reportUnit:'',month:new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0'),kind:'monthly',reportLoading:false,reportPage:0,reportMore:false,stageTrack:null,stageSignature:'',annotationSignature:'',recorder:null,recording:null,starting:false};
const huddleIconPaths={copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',exit:'<path d="M9 3H3v18h6M9 12h12m-5-5 5 5-5 5"/>',record:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3" fill="currentColor"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',arrow:'<path d="M4 20 20 4M9 4h11v11"/>',pointer:'<path d="m5 3 14 9-7 2-3 7Z"/>',erase:'<path d="m3 14 9-11 9 8-9 10H8ZM8 21h13M8 9l9 8"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',chat:'<path d="M3 4h18v13H9l-6 4Z"/><path d="M7 8h10M7 12h7"/>'};
function huddleStudioIcon(name){return huddleIconPaths[name]?'<svg class="i" viewBox="0 0 24 24" aria-hidden="true">'+huddleIconPaths[name]+'</svg>':icon(name);}
function huddleIconButton(name,label,action,extra=''){return '<button type="button" class="huddle-tool" title="'+e(label)+'" aria-label="'+e(label)+'" onclick="'+e(action)+'" '+extra+'>'+huddleStudioIcon(name)+'<span class="sr-only">'+e(label)+'</span></button>';}
function huddleStudioUnitControl(){return S.role==='Admin'?'<label>Operating unit<select name="unit">'+huddleUnitOptions()+'</select></label>':huddleUnitControl();}
function huddleStudioHeader(title,meeting=false){const c=HUDDLE.context;return '<header class="huddle-studio-header"><a class="huddle-wordmark" href="#main" onclick="event.preventDefault();huddleExit()">'+logo()+'<span><strong>OCCCI HUDDLE</strong><small>by OCCCI Connect</small></span></a><div class="huddle-studio-title"><span>'+(meeting?'LIVE SESSION':'COLLABORATION WORKSPACE')+'</span><h1>'+e(title)+'</h1></div><div class="huddle-studio-header-actions"><span data-huddle-recording class="huddle-rec-badge" hidden>● REC</span>'+(meeting?'<span class="huddle-connection-pill" data-huddle-connection>Connected</span>':'')+(meeting&&c?.is_host?huddleIconButton('copy','Copy code','huddleCopyCode()'):'')+(meeting?huddleIconButton('grid','Sessions','huddleOpenSessions()'):'')+huddleIconButton('exit','Return to OCCCI Connect without leaving the call','huddleExit()')+'</div></header>';}
function huddleExit(){go(S.role==='BC'?'Cashier':isStaff()?'Overview':'Home');}
const huddleStudioOriginalView=huddleView;
huddleView=function(){if(HUDDLE.room&&HUDDLE.context&&HUDDLE.view==='meeting')return huddleMeetingView();return huddleStudioHeader('Sessions')+'<div class="huddle-studio-lobby">'+huddleStudioOriginalView()+'</div>';};
huddleMeetingView=function(){const c=HUDDLE.context,host=c.is_host,ready=c.studio_ready===true;
 return '<section class="huddle-meeting huddle-studio">'+huddleStudioHeader(c.session.title,true)+
 '<p class="huddle-room-error" data-huddle-error role="alert" hidden></p>'+
 (!ready?'<p class="huddle-setup" data-huddle-studio-setup>Presentation, drawing and recording controls require Huddle studio update 027. '+(S.role==='Admin'?'<a href="huddle-studio-update.sql?v=52" download="OCCCI-Huddle-Studio-Update.sql">Download SQL update</a>':'Ask your administrator to apply the studio update.')+'</p>':'')+
 '<div class="huddle-gallery"><div class="huddle-gallery-label"><span>Participants</span><strong data-huddle-people-count></strong></div><div class="huddle-video-grid" data-huddle-people></div></div>'+
 '<div class="huddle-workspace huddle-studio-workspace"><div class="huddle-stage"><div class="huddle-stage-label"><span data-huddle-stage-title>Presentation</span>'+huddleIconButton('expand','Expand presentation','huddleExpandStage()')+'</div>'+
 '<div class="huddle-big-screen" data-huddle-big-screen><div class="huddle-screen-stage" data-huddle-screens hidden></div><div class="huddle-stage-content" data-huddle-stage-content></div><svg class="huddle-annotation-layer" viewBox="0 0 1000 562.5" preserveAspectRatio="none" aria-label="Shared presentation drawings" data-huddle-annotations></svg></div>'+
 '<div class="huddle-controls">'+huddleIconButton('mic','Microphone','huddleToggle(\'mic\')','data-huddle-control="mic"')+huddleIconButton('camera','Camera','huddleToggle(\'camera\')','data-huddle-control="camera"')+huddleIconButton('share','Share screen','huddleToggle(\'screen\')','data-huddle-control="screen"')+huddleIconButton('support','Enable sound','huddleStartAudio()','data-huddle-audio hidden')+
 (host?huddleIconButton('record','Start or stop recording on this device','huddleRecordDialog()','data-huddle-record-control '+(!ready?'disabled':''))+huddleIconButton('micOff','Mute all attendees','huddleModerate(\'mute_all\')')+huddleIconButton('mic','Allow attendees to turn on their microphones','huddleModerate(\'allow_all\')'):'')+
 huddleIconButton('close','Leave this session','huddleLeave()','data-huddle-leave')+(host?huddleIconButton('stop','End session for everyone','huddleEndDialog()'):'')+'</div><p class="huddle-mic-note" data-huddle-mic-note role="status"></p></div>'+
 '<aside class="huddle-collaboration card"><div class="huddle-panel-title" data-huddle-panel-title>Attendees</div><div class="tabs huddle-tabs">'+huddleIconButton('users','Attendees','huddleTab(\'attendees\')','data-huddle-tab="attendees"')+huddleIconButton('chat','Chat','huddleTab(\'chat\')','data-huddle-tab="chat"')+(isStaff()?huddleIconButton('chart','Reports and data','huddleTab(\'data\')','data-huddle-tab="data"'):'')+'</div>'+
 '<section data-huddle-pane="attendees"><div data-huddle-roster></div></section>'+
 '<section data-huddle-pane="chat" hidden><div class="huddle-chat-list" data-huddle-chat aria-live="polite"></div><form class="huddle-chat-form" onsubmit="event.preventDefault();huddleSendChat(this)"><label class="sr-only" for="huddleChatInput">Message</label><textarea id="huddleChatInput" name="message" placeholder="Message this Huddle" required maxlength="2000" rows="2"></textarea>'+huddleIconButton('arrow','Send message','this.form.requestSubmit()')+'</form></section>'+
 (isStaff()?'<section data-huddle-pane="data" hidden><h2>District & branch reports</h2><p class="hint">Only approved reports within your authorized units are available.</p><form class="huddle-report-form" onsubmit="event.preventDefault();huddleLoadReports(this)">'+huddleStudioUnitControl()+'<label>Month<input type="month" name="month" required value="'+e(HUDDLE_STUDIO.month)+'" onchange="HUDDLE_STUDIO.month=this.value"></label><label>Report type<select name="kind" onchange="HUDDLE_STUDIO.kind=this.value"><option value="monthly">Monthly transactions</option><option value="project">Special projects</option></select></label>'+huddleIconButton('search','Find approved reports','this.form.requestSubmit()',!ready?'disabled':'')+'</form><div data-huddle-reports class="huddle-report-list"></div><details class="huddle-summary-tools"><summary>Verified balance snapshot</summary><form class="huddle-data-form" onsubmit="event.preventDefault();huddleLoadData(this)">'+huddleUnitControl()+huddleIconButton('chart','Load verified balances','this.form.requestSubmit()')+'</form><div data-huddle-data></div><div data-huddle-shared></div></details></section>':'')+'</aside>'+
 '<nav class="huddle-tool-rail" aria-label="Presentation tools">'+huddleIconButton('pointer','Select and view','huddleDrawingTool(\'pointer\')','data-huddle-drawing="pointer"')+huddleIconButton('edit','Draw with pen','huddleDrawingTool(\'pen\')','data-huddle-drawing="pen"')+huddleIconButton('arrow','Draw arrow','huddleDrawingTool(\'arrow\')','data-huddle-drawing="arrow"')+'<span class="huddle-tool-divider"></span>'+huddleIconButton('camera','Present a camera','huddlePresentHostCamera()',!host||!ready?'disabled':'')+huddleIconButton('share','Present a shared screen','huddlePresentScreen()',!host||!ready?'disabled':'')+(host?huddleIconButton('erase','Clear shared drawings','huddleStudioCommand(\'clear\')',!ready?'disabled':''):'')+'<span class="huddle-tool-divider"></span><button type="button" class="huddle-color is-cyan" title="Cyan ink" aria-label="Cyan ink" onclick="huddleDrawingColor(\'cyan\')" data-huddle-color="cyan"></button><button type="button" class="huddle-color is-red" title="Red ink" aria-label="Red ink" onclick="huddleDrawingColor(\'red\')" data-huddle-color="red"></button></nav></div></section>';
};
const huddleStudioOriginalBefore=huddleBeforeRender;
huddleBeforeRender=function(){huddleStudioOriginalBefore();document.body.classList.toggle('huddle-studio-page',S.page==='Huddle'&&huddleCanJoin());};
const huddleStudioOriginalMount=huddleMount;
huddleMount=function(){huddleStudioOriginalMount();if(S.page==='Huddle'){document.title='OCCCI Huddle · OCCCI Connect';huddleStudioMount();}};
function huddleStudioMount(){const form=document.querySelector('.huddle-report-form');if(form){if(HUDDLE_STUDIO.reportUnit&&[...form.elements.unit.options||[]].some(o=>o.value===HUDDLE_STUDIO.reportUnit))form.elements.unit.value=HUDDLE_STUDIO.reportUnit;form.elements.kind.value=HUDDLE_STUDIO.kind;huddleReportList();}const svg=document.querySelector('[data-huddle-annotations]');if(svg&&!svg.dataset.bound){svg.dataset.bound='true';svg.addEventListener('pointerdown',huddleDrawStart);svg.addEventListener('pointermove',huddleDrawMove);svg.addEventListener('pointerup',huddleDrawEnd);svg.addEventListener('pointercancel',()=>{HUDDLE_STUDIO.draft=null;huddleDrawRender();});}huddleStudioUpdate();}
const huddleStudioOriginalPeople=huddleUpdatePeople;
huddleUpdatePeople=function(){huddleStudioOriginalPeople();const c=HUDDLE.context,room=HUDDLE.room;if(!c||!room)return;const people=[room.localParticipant,...room.remoteParticipants.values()];document.querySelectorAll('[data-huddle-person]').forEach(tile=>{if(c.is_host){tile.setAttribute('role','button');tile.tabIndex=0;tile.title='Present this camera';tile.setAttribute('aria-label','Present '+(tile.querySelector('strong')?.textContent||'participant')+' camera');tile.onclick=()=>huddleStudioCommand('camera',tile.dataset.huddlePerson);tile.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();tile.click();}};}});const count=document.querySelector('[data-huddle-people-count]');if(count)count.textContent=people.length;const roster=document.querySelector('[data-huddle-roster]');if(roster)roster.innerHTML=people.map(p=>{const info=c.participants.find(a=>a.user_id===p.identity),host=p.identity===c.session.host_id;return '<div class="huddle-attendee"><div><strong>'+e(info?.name||p.name||'Participant')+'</strong><small>'+e(host?'Host':roleLabel(info?.role||'Member'))+'</small></div><div class="huddle-attendee-tools">'+(c.is_host&&!host?huddleIconButton(info?.mic_locked?'mic':'micOff',info?.mic_locked?'Allow microphone':'Mute microphone','huddleModerate(\''+(info?.mic_locked?'allow':'mute')+'\',\''+p.identity+'\')')+huddleIconButton('edit',info?.annotation_allowed?'Revoke drawing permission':'Allow drawing','huddleStudioCommand(\''+(info?.annotation_allowed?'revoke_pen':'grant_pen')+'\',\''+p.identity+'\')','aria-pressed="'+Boolean(info?.annotation_allowed)+'" '+(!c.studio_ready?'disabled':'')):'')+'</div></div>';}).join('');};
const huddleStudioOriginalSync=huddleSyncTracks;
huddleSyncTracks=function(){huddleStudioOriginalSync();huddleStudioUpdate();};
const huddleStudioOriginalCollaboration=huddleUpdateCollaboration;
huddleUpdateCollaboration=function(){huddleStudioOriginalCollaboration();const preview=document.querySelector('[data-huddle-data]');if(preview&&HUDDLE.data)preview.innerHTML=huddleDataCard(HUDDLE.data.summary)+huddleIconButton('share','Share verified data card with authorized staff','huddleShareData()');huddleStudioUpdate();};
const huddleStudioOriginalTab=huddleTab;
huddleTab=function(tab){huddleStudioOriginalTab(tab);const title=document.querySelector('[data-huddle-panel-title]');if(title)title.textContent=tab==='data'?'Reports & data':tab==='chat'?'Session chat':'Attendees';};
const huddleStudioOriginalMedia=huddleSetMedia;
huddleSetMedia=async function(kind,on){await huddleStudioOriginalMedia(kind,on);if(!HUDDLE.context?.is_host||!HUDDLE.context.studio_ready)return;const local=HUDDLE.room?.localParticipant;if(kind==='camera'&&on&&local?.isCameraEnabled)await huddleStudioCommand('camera',local.identity);if(kind==='screen'&&on&&local?.isScreenShareEnabled)await huddleStudioCommand('screen',local.identity);};
const huddleStudioOriginalDialog=huddleJoinDialog;
huddleJoinDialog=function(sid='',code=''){if(HUDDLE.room&&sid===HUDDLE.context?.session.id){huddleReturn();return;}const session=HUDDLE.sessions.find(s=>s.id===sid);if(!HUDDLE.room&&!HUDDLE.busy&&session?.can_resume){HUDDLE.selectedSession=sid;huddleConnect('resume',{sessionId:sid},false,false);return;}huddleStudioOriginalDialog(sid,code);};
const huddleStudioOriginalConnect=huddleConnect;
huddleConnect=async function(...args){await huddleStudioOriginalConnect(...args);if(HUDDLE.context?.is_host&&HUDDLE.context.studio_ready&&!HUDDLE.context.presentation)await huddleStudioCommand('camera',HUDDLE.context.session.host_id);};
async function huddleStudioCommand(command,target=null,values={}){const c=HUDDLE.context;if(!c?.studio_ready){huddleShowError(Error('Apply Huddle studio update 027 before using presentation tools.'));return;}const epoch=HUDDLE.epoch;try{const result=await huddleApi('studio',{sessionId:c.session.id,command,target,...values});if(epoch!==HUDDLE.epoch)return;HUDDLE.context=result.context;huddleUpdatePeople();huddleUpdateControls();huddleStudioUpdate();return true;}catch(error){if(epoch===HUDDLE.epoch)huddleShowError(error);return false;}}
function huddlePresentHostCamera(){if(HUDDLE.context?.is_host)huddleStudioCommand('camera',HUDDLE.context.session.host_id);}
function huddlePresentScreen(){if(!HUDDLE.context?.is_host)return;const people=[HUDDLE.room.localParticipant,...HUDDLE.room.remoteParticipants.values()],p=people.find(p=>p.isScreenShareEnabled||p.getTrackPublication(window.LivekitClient.Track.Source.ScreenShare)?.track);if(p)huddleStudioCommand('screen',p.identity);else toast('Share a screen first.');}
function huddleStageDescriptor(){const c=HUDDLE.context,room=HUDDLE.room;if(!c||!room)return null;const people=[room.localParticipant,...room.remoteParticipants.values()],stage=c.presentation;if(stage?.kind==='report')return stage;const screen=people.find(p=>p.getTrackPublication(window.LivekitClient.Track.Source.ScreenShare)?.track);return stage||{kind:screen?'screen':'camera',target:screen?.identity||c.session.host_id,revision:null};}
function huddleDetachStage(){const item=HUDDLE_STUDIO.stageTrack;if(item){item.track.detach(item.element);item.element.remove();HUDDLE_STUDIO.stageTrack=null;}}
function huddleReportMarkup(r){return '<article class="huddle-presented-report"><div class="huddle-report-kicker">'+e(r.source==='work'?'MONTHLY TRANSACTION REPORT':'SPECIAL PROJECT REPORT')+'</div><h2>'+e(r.title)+'</h2><p class="huddle-report-period">District '+e(r.district||'—')+' · '+e(r.branch_id?bn(r.branch_id)+' Branch':'District report')+' · '+e(r.period_start)+' — '+e(r.period_end)+'</p><p class="huddle-report-summary">'+e(r.summary)+'</p><dl>'+Object.entries(r.metrics||{}).filter(([k,v])=>!['staff_work_id','author','documents'].includes(k)&&v!==null&&['number','string','boolean'].includes(typeof v)).slice(0,16).map(([k,v])=>'<div><dt>'+e(k.replace(/_/g,' '))+'</dt><dd>'+e(typeof v==='number'?new Intl.NumberFormat('en-PH').format(v):v)+'</dd></div>').join('')+'</dl><footer>'+e(r.status)+' · Approved source record · Values remain subject to your operating-unit access.</footer></article>';}
function huddleStudioUpdate(){const c=HUDDLE.context,room=HUDDLE.room,root=document.querySelector('[data-huddle-stage-content]');if(!c||!room||!root)return;const stage=huddleStageDescriptor(),people=[room.localParticipant,...room.remoteParticipants.values()],p=people.find(p=>p.identity===stage.target),source=stage.kind==='screen'?window.LivekitClient.Track.Source.ScreenShare:window.LivekitClient.Track.Source.Camera,pub=p?.getTrackPublication(source),name=c.participants.find(a=>a.user_id===p?.identity)?.name||p?.name||'Participant',signature=JSON.stringify([stage,Boolean(pub?.track&&!pub.isMuted),name]);
 if(root.dataset.signature!==signature){huddleDetachStage();root.dataset.signature=signature;root.innerHTML=stage.kind==='report'?(stage.restricted?'<div class="huddle-stage-placeholder">'+icon('shield')+'<strong>Report access restricted</strong><p>This presentation is outside your authorized operating units.</p></div>':huddleReportMarkup(stage.report)):'<div class="huddle-stage-placeholder">'+icon(stage.kind==='screen'?'share':'camera')+'<strong>'+e(name)+'</strong><p>'+(stage.kind==='screen'?'Waiting for the shared screen.':'Camera is off. The host can choose a participant to present.')+'</p></div>';}
 if(stage.kind!=='report'&&pub?.track&&!pub.isMuted){if(HUDDLE_STUDIO.stageTrack?.track!==pub.track||!HUDDLE_STUDIO.stageTrack.element.isConnected){huddleDetachStage();const element=pub.track.attach();element.autoplay=true;element.playsInline=true;element.muted=true;element.className='huddle-stage-video';root.append(element);HUDDLE_STUDIO.stageTrack={track:pub.track,element};}}
 else huddleDetachStage();
 const title=document.querySelector('[data-huddle-stage-title]');if(title)title.textContent=stage.kind==='report'?(stage.restricted?'Authorized report presentation':stage.report?.title||'Report'):name+(stage.kind==='screen'?' · Screen share':' · Camera');
 const setup=document.querySelector('[data-huddle-studio-setup]');if(setup)setup.hidden=c.studio_ready===true;
 document.querySelectorAll('.huddle-tool-rail button[onclick^="huddlePresent"],.huddle-tool-rail button[onclick^="huddleStudioCommand"]').forEach(b=>b.disabled=!c.is_host||!c.studio_ready);
 const findReports=document.querySelector('.huddle-report-form button');if(findReports)findReports.disabled=!c.studio_ready;
 const rec=document.querySelector('[data-huddle-recording]');if(rec)rec.hidden=!c.recording&&!HUDDLE_STUDIO.recorder;
 const rb=document.querySelector('[data-huddle-record-control]');if(rb){rb.classList.toggle('is-recording',Boolean(HUDDLE_STUDIO.recorder));rb.disabled=!c.studio_ready||HUDDLE_STUDIO.starting;rb.title=HUDDLE_STUDIO.recorder?'Stop and save recording':'Record on this device';rb.setAttribute('aria-label',rb.title);rb.innerHTML=huddleStudioIcon(HUDDLE_STUDIO.recorder?'stop':'record')+'<span class="sr-only">'+e(rb.title)+'</span>';}
 if(!c.annotation_allowed||stage.restricted)HUDDLE_STUDIO.tool='pointer';huddleDrawControls();huddleDrawRender();huddleRecordAudioSync();
}
async function huddleLoadReports(form,page=0){if(HUDDLE_STUDIO.reportLoading)return;const epoch=HUDDLE.epoch;HUDDLE_STUDIO.reportLoading=true;HUDDLE_STUDIO.reportPage=page;HUDDLE_STUDIO.reportMore=false;HUDDLE_STUDIO.reportUnit=form.elements.unit.value;HUDDLE_STUDIO.month=form.elements.month.value;HUDDLE_STUDIO.kind=form.elements.kind.value;HUDDLE_STUDIO.reports=[];huddleReportList();try{const result=await huddleApi('reports',{sessionId:HUDDLE.context.session.id,...huddleUnit(HUDDLE_STUDIO.reportUnit),month:HUDDLE_STUDIO.month+'-01',kind:HUDDLE_STUDIO.kind,page});if(epoch===HUDDLE.epoch){HUDDLE_STUDIO.reportMore=result.reports.length>100;HUDDLE_STUDIO.reports=result.reports.slice(0,100);}}catch(error){if(epoch===HUDDLE.epoch)huddleShowError(error);}finally{if(epoch===HUDDLE.epoch){HUDDLE_STUDIO.reportLoading=false;huddleReportList();}}}
function huddleReportPage(page){const form=document.querySelector('.huddle-report-form');if(form)huddleLoadReports(form,page);}
function huddleReportList(){const root=document.querySelector('[data-huddle-reports]');if(root)root.innerHTML=HUDDLE_STUDIO.reportLoading?'<p class="hint">Loading approved reports…</p>':HUDDLE_STUDIO.reports.length?HUDDLE_STUDIO.reports.map(r=>'<article><div><strong>'+e(r.title)+'</strong><small>District '+e(r.district)+' · '+e(r.branch_id?bn(r.branch_id):'District')+' · '+e(r.period_start)+'</small></div>'+huddleIconButton('share','Present '+r.title,'huddleStudioCommand(\'report\',null,{reportId:\''+r.id+'\',source:\''+r.source+'\'})')+'</article>').join(''):'<p class="hint">Choose a month and find approved reports. Unapproved reports are excluded.</p>';if(root&&!HUDDLE_STUDIO.reportLoading&&(HUDDLE_STUDIO.reportPage||HUDDLE_STUDIO.reportMore))root.innerHTML+='<div class="huddle-report-pages"><span>Page '+(HUDDLE_STUDIO.reportPage+1)+'</span>'+huddleIconButton('up','Previous report page','huddleReportPage('+(HUDDLE_STUDIO.reportPage-1)+')',HUDDLE_STUDIO.reportPage?'':'disabled')+huddleIconButton('down','Next report page','huddleReportPage('+(HUDDLE_STUDIO.reportPage+1)+')',HUDDLE_STUDIO.reportMore?'':'disabled')+'</div>';}
function huddleDrawingTool(tool){if(!['pointer','pen','arrow'].includes(tool))return;if(tool!=='pointer'&&(!HUDDLE.context?.studio_ready||!HUDDLE.context.annotation_allowed||huddleStageDescriptor()?.restricted)){toast('The host must allow drawing on this presentation.');return;}HUDDLE_STUDIO.tool=tool;huddleDrawControls();}
function huddleDrawingColor(color){if(['red','cyan'].includes(color))HUDDLE_STUDIO.color=color;huddleDrawControls();}
function huddleDrawControls(){const c=HUDDLE.context,allowed=c?.studio_ready&&c.annotation_allowed&&!huddleStageDescriptor()?.restricted;document.querySelectorAll('[data-huddle-drawing]').forEach(b=>{b.disabled=b.dataset.huddleDrawing!=='pointer'&&!allowed;b.setAttribute('aria-pressed',String(b.dataset.huddleDrawing===HUDDLE_STUDIO.tool));});document.querySelectorAll('[data-huddle-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.huddleColor===HUDDLE_STUDIO.color)));const svg=document.querySelector('[data-huddle-annotations]');if(svg)svg.classList.toggle('is-drawing',allowed&&HUDDLE_STUDIO.tool!=='pointer');}
function huddlePoint(ev){const rect=ev.currentTarget.getBoundingClientRect();return [Math.max(0,Math.min(1,(ev.clientX-rect.left)/rect.width)),Math.max(0,Math.min(1,(ev.clientY-rect.top)/rect.height))];}
function huddleDrawStart(ev){if(HUDDLE_STUDIO.tool==='pointer'||!HUDDLE.context?.annotation_allowed||!HUDDLE.context.presentation?.revision||huddleStageDescriptor()?.restricted)return;ev.preventDefault();ev.currentTarget.setPointerCapture?.(ev.pointerId);HUDDLE_STUDIO.draft={tool:HUDDLE_STUDIO.tool,color:HUDDLE_STUDIO.color,revision:HUDDLE.context.presentation.revision,points:[huddlePoint(ev)]};}
function huddleDrawMove(ev){const d=HUDDLE_STUDIO.draft;if(!d)return;ev.preventDefault();const point=huddlePoint(ev);if(d.tool==='arrow')d.points=[d.points[0],point];else if(d.points.length<120)d.points.push(point);huddleDrawRender();}
async function huddleDrawEnd(ev){const d=HUDDLE_STUDIO.draft;if(!d)return;HUDDLE_STUDIO.draft=null;ev.currentTarget.releasePointerCapture?.(ev.pointerId);if(d.points.length===1)d.points.push(huddlePoint(ev));await huddleStudioCommand('stroke',null,{stroke:d});huddleDrawRender();}
function huddleStrokeMarkup(s){const points=s.points.map(p=>[p[0]*1000,p[1]*562.5]),color=s.color==='red'?'#ef285a':'#00d4e6';let path=points.map((p,i)=>(i?'L':'M')+p[0].toFixed(2)+' '+p[1].toFixed(2)).join(' ');if(s.tool==='arrow'&&points.length>1){const a=points[0],b=points.at(-1),angle=Math.atan2(b[1]-a[1],b[0]-a[0]),size=16;path+=' M'+(b[0]-size*Math.cos(angle-.5))+' '+(b[1]-size*Math.sin(angle-.5))+' L'+b[0]+' '+b[1]+' L'+(b[0]-size*Math.cos(angle+.5))+' '+(b[1]-size*Math.sin(angle+.5));}return '<path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>';}
function huddleDrawRender(){const svg=document.querySelector('[data-huddle-annotations]');if(!svg)return;const stage=huddleStageDescriptor(),strokes=stage?.restricted?[]:[...(HUDDLE.context?.strokes||[]),...(HUDDLE_STUDIO.draft?[HUDDLE_STUDIO.draft]:[])];const signature=JSON.stringify(strokes);if(svg.dataset.signature!==signature){svg.innerHTML=strokes.map(huddleStrokeMarkup).join('');svg.dataset.signature=signature;}}
function huddleExpandStage(){const stage=document.querySelector('[data-huddle-big-screen]');if(document.fullscreenElement)document.exitFullscreen?.();else if(stage?.requestFullscreen)stage.requestFullscreen().catch(huddleShowError);}
function huddleRecordDialog(){if(!HUDDLE.context?.is_host||!HUDDLE.context.studio_ready)return;if(HUDDLE_STUDIO.recorder){huddleStopRecording();return;}openModal('Record OCCCI Huddle','<p>Record the presentation and available session audio on this device. Attendees will see a recording indicator. The video downloads when recording stops; it is not stored in the cooperative database.</p><p class="hint">Use a supported desktop browser. Keep this tab open until the video is saved.</p><button type="button" class="primary" onclick="closeModal();huddleStartRecording()">Start recording</button>');}
async function huddleStartRecording(){if(HUDDLE_STUDIO.starting||HUDDLE_STUDIO.recorder||!HUDDLE.context?.is_host||!HUDDLE.context.studio_ready)return;const epoch=HUDDLE.epoch;let recording;try{if(!window.MediaRecorder||!window.HTMLCanvasElement.prototype.captureStream)throw Error('Recording is unavailable in this browser. Use a supported desktop browser.');HUDDLE_STUDIO.starting=true;const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=800;const stream=canvas.captureStream(20);recording={stream,audio:null};const Audio=window.AudioContext||window.webkitAudioContext,audio=Audio?new Audio():null,destination=audio?.createMediaStreamDestination();recording.audio=audio;if(destination)for(const t of destination.stream.getAudioTracks())stream.addTrack(t);const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('This browser cannot save a supported video format.');const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:1800000});recording={canvas,stream,audio,destination,connections:new Map(),chunks:[],size:0,timer:null,recorder,title:HUDDLE.context.session.title,started:Date.now(),sid:HUDDLE.context.session.id};
 if(!await huddleStudioCommand('record_start'))throw Error('Recording was not authorized.');if(epoch!==HUDDLE.epoch)throw Error('The session changed before recording began.');
 HUDDLE_STUDIO.recording=recording;HUDDLE_STUDIO.recorder=recorder;
 recorder.ondataavailable=ev=>{if(ev.data.size){recording.chunks.push(ev.data);recording.size+=ev.data.size;if(recording.size>200*1024*1024){toast('Recording reached its size limit and is being saved.');huddleStopRecording();}}};
 recorder.onstop=()=>huddleSaveRecording(recording);recorder.onerror=()=>{huddleShowError(Error('Recording stopped unexpectedly. Saving available video.'));huddleStopRecording();};
 recording.timer=setInterval(()=>huddleRecordFrame(recording),50);huddleRecordFrame(recording);huddleRecordAudioSync();await audio?.resume();if(epoch!==HUDDLE.epoch||HUDDLE_STUDIO.recording!==recording)throw Error('The session changed before recording began.');recorder.start(1000);recording.ping=setInterval(()=>huddleStudioCommand('record_ping'),20000);huddleStudioUpdate();toast('Recording started. It will save on this device.');
 }catch(error){if(recording){clearInterval(recording.timer);recording.stream.getTracks().forEach(t=>t.stop());recording.audio?.close();}if(HUDDLE_STUDIO.recording===recording){HUDDLE_STUDIO.recorder=null;HUDDLE_STUDIO.recording=null;}if(epoch===HUDDLE.epoch){huddleStudioCommand('record_stop');huddleShowError(error);}}
 finally{HUDDLE_STUDIO.starting=false;huddleStudioUpdate();}}
function huddleRecordAudioSync(){const r=HUDDLE_STUDIO.recording,room=HUDDLE.room;if(!r?.audio||!room)return;const wanted=new Set();for(const p of [room.localParticipant,...room.remoteParticipants.values()])for(const pub of p.audioTrackPublications.values()){const track=pub.track?.mediaStreamTrack;if(!track||pub.isMuted||p===room.localParticipant&&!p.isMicrophoneEnabled)continue;wanted.add(track.id);if(!r.connections.has(track.id)){const node=r.audio.createMediaStreamSource(new MediaStream([track]));node.connect(r.destination);r.connections.set(track.id,node);}}for(const [key,node] of r.connections)if(!wanted.has(key)){node.disconnect();r.connections.delete(key);}}
function huddleCanvasVideo(ctx,video,x,y,w,h){if(video?.readyState>=2){const ratio=Math.min(w/video.videoWidth,h/video.videoHeight),vw=video.videoWidth*ratio,vh=video.videoHeight*ratio;ctx.drawImage(video,x+(w-vw)/2,y+(h-vh)/2,vw,vh);}}
function huddleRecordFrame(r){const ctx=r.canvas.getContext('2d');if(!ctx)return;ctx.fillStyle='#102b4b';ctx.fillRect(0,0,1280,800);ctx.fillStyle='#ffffff';ctx.font='bold 20px sans-serif';ctx.fillText('OCCCI HUDDLE · '+r.title.slice(0,70),24,32);ctx.font='12px sans-serif';ctx.fillText('REC · '+new Date().toLocaleString('en-PH'),24,54);const videos=[...document.querySelectorAll('[data-huddle-camera] video')];videos.slice(0,8).forEach((v,i)=>huddleCanvasVideo(ctx,v,24+i*154,68,144,82));const stage=huddleStageDescriptor();if(stage?.kind==='report'&&!stage.restricted){ctx.fillStyle='#ffffff';ctx.fillRect(24,166,1232,600);ctx.fillStyle='#17324d';ctx.font='bold 25px sans-serif';ctx.fillText(stage.report.title.slice(0,85),48,212);ctx.font='15px sans-serif';ctx.fillText(stage.report.period_start+' — '+stage.report.period_end,48,246);const words=(stage.report.summary||'').split(/\s+/);let line='',y=278;for(const word of words){if(ctx.measureText(line+word).width>1150){ctx.fillText(line,48,y);y+=24;line='';if(y>380)break;}line+=word+' ';}ctx.fillText(line,48,y);Object.entries(stage.report.metrics||{}).filter(([,v])=>['number','string','boolean'].includes(typeof v)).slice(0,12).forEach(([k,v],i)=>{ctx.fillText(k.replace(/_/g,' ')+': '+String(v).slice(0,80),48+(i%2)*580,430+Math.floor(i/2)*42);});}else huddleCanvasVideo(ctx,HUDDLE_STUDIO.stageTrack?.element,24,166,1232,600);
 for(const s of HUDDLE.context?.strokes||[]){ctx.strokeStyle=s.color==='red'?'#ef285a':'#00d4e6';ctx.lineWidth=4;ctx.beginPath();s.points.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](24+p[0]*1232,166+p[1]*600));if(s.tool==='arrow'){const a=s.points[0],b=s.points.at(-1),angle=Math.atan2((b[1]-a[1])*600,(b[0]-a[0])*1232),x=24+b[0]*1232,y=166+b[1]*600;ctx.moveTo(x-18*Math.cos(angle-.5),y-18*Math.sin(angle-.5));ctx.lineTo(x,y);ctx.lineTo(x-18*Math.cos(angle+.5),y-18*Math.sin(angle+.5));}ctx.stroke();}
}
function huddleStopRecording(notify=true){const r=HUDDLE_STUDIO.recording;if(!r)return;HUDDLE_STUDIO.recorder=null;HUDDLE_STUDIO.recording=null;clearInterval(r.timer);clearInterval(r.ping);if(r.recorder.state!=='inactive')r.recorder.stop();else huddleSaveRecording(r);if(notify&&HUDDLE.context?.studio_ready)huddleStudioCommand('record_stop');huddleStudioUpdate();}
function huddleSaveRecording(r){if(r.saved)return;r.saved=true;r.stream.getTracks().forEach(t=>t.stop());for(const n of r.connections.values())n.disconnect();r.audio?.close();if(!r.chunks.length)return;const blob=new Blob(r.chunks,{type:r.recorder.mimeType}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='OCCCI-Huddle-'+r.started+(r.recorder.mimeType.includes('mp4')?'.mp4':'.webm');a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);r.chunks=[];toast('Huddle recording saved on this device.');}
const huddleStudioOriginalReset=huddleReset;
huddleReset=function(){huddleStopRecording(false);huddleDetachStage();HUDDLE_STUDIO.draft=null;HUDDLE_STUDIO.reports=[];HUDDLE_STUDIO.tool='pointer';HUDDLE_STUDIO.reportUnit='';HUDDLE_STUDIO.reportLoading=false;huddleStudioOriginalReset();};
// Visible action buttons use icons; accessible names and hover hints remain available.
function huddleIconizeActions(root){if(!root)return;for(const b of root.querySelectorAll('button')){if(b.classList.contains('huddle-session-open')||b.classList.contains('huddle-tool')||b.classList.contains('huddle-color'))continue;const label=b.getAttribute('aria-label')||b.textContent.trim();if(!label)continue;const key=/copy/i.test(label)?'copy':/end/i.test(label)?'stop':/done/i.test(label)?'check':/refresh/i.test(label)?'switch':/creat/i.test(label)?'plus':/join|return/i.test(label)?'video':/leave/i.test(label)?'exit':null;if(!key)continue;b.title=label;b.setAttribute('aria-label',label);b.classList.add('huddle-icon-action');b.innerHTML=huddleStudioIcon(key)+'<span class="sr-only">'+e(label)+'</span>';}}
